/*
 * A121293  a(n) = Bell(3*n+2).
 * https://oeis.org/A121293
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = Bell(3*n + 2) Computation: Bell numbers are generated by
 *            the recurrence B(0) = 1 B(m+1) = Σ_{k=0}^{m} binom(m,k) * B(k)
 *            The routine memoises the values in a static array so that each n
 *            can be queried in any order
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 4, u64 n <= 7, u128 n <= 13,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>    /* malloc, free, exit */

static seq_t *bell_cache = NULL;
static idx_t bell_cache_size = 0;

/* Grow the cache so that it contains Bell numbers up to `max_k`. */
static void ensure_bell_cache(idx_t max_k)
{
    if (max_k < bell_cache_size) return;

    /* Determine new capacity (double until enough) */
    idx_t new_cap = bell_cache_size == 0 ? 1 : bell_cache_size;
    while (new_cap <= max_k) new_cap <<= 1;

    seq_t *new_arr = (seq_t *)malloc(new_cap * sizeof(seq_t));
    if (!new_arr) exit(EXIT_FAILURE);    /* allocation failed */

    /* Copy old data if present */
    if (bell_cache != NULL) {
        for (idx_t i = 0; i < bell_cache_size; ++i) new_arr[i] = bell_cache[i];
        free(bell_cache);
    }
    bell_cache = new_arr;

    /* Initialize new entries to zero */
    for (idx_t i = bell_cache_size; i < new_cap; ++i) bell_cache[i] = (seq_t)0;

    /* Compute missing Bell numbers */
    for (idx_t n = bell_cache_size; n < new_cap; ++n) {
        if (n == 0) {
            bell_cache[0] = (seq_t)1;          /* B(0)=1 */
            continue;
        }
        seq_t sum   = (seq_t)0;
        seq_t binom = (seq_t)1;                /* binom(n-1,0) */
        idx_t  m    = n - 1;
        for (idx_t k = 0; k <= m; ++k) {
            sum += binom * bell_cache[k];
            if (k < m) {
                /* binom = binom * (m - k) / (k + 1) */
                binom = (binom * (m - k)) / (k + 1);
            }
        }
        bell_cache[n] = sum;
    }

    bell_cache_size = new_cap;
}

seq_t a(idx_t n)
{
    /* a(n) = Bell(3*n + 2) */
    idx_t k = 3 * n + 2;
    if (k >= bell_cache_size) ensure_bell_cache(k);
    return bell_cache[k];
}
